-- Isolated Kiongozi Public Participation schema. Idempotent and UTF-8 under PostgreSQL.
create extension if not exists pgcrypto;
create or replace function public.participation_is_staff() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(auth.jwt()->'app_metadata'->>'role','') in ('admin','moderator') $$;
create table if not exists public.participation_opportunities(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,institution text not null,opportunity_type text not null check(opportunity_type in ('bill_legislative','national_budget','county_budget','county_forum','ministry','national_strategy','other')),scope text not null check(scope in ('national','county')),county text,opens_at timestamptz not null,closes_at timestamptz not null,status text not null default 'draft' check(status in ('draft','open','closed','archived')),official_source_url text,plain_summary text,key_issues jsonb not null default '[]',channels text[] not null default '{web}',is_demo boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(closes_at>opens_at),check(scope='national' or county is not null));
create table if not exists public.participation_questions(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete cascade,prompt text not null,question_type text not null check(question_type in ('single','multiple')),options jsonb not null,position integer not null default 0,is_required boolean not null default true,is_demo boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.participation_source_documents(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete cascade,title text not null,source_url text not null,source_text text,citations jsonb not null default '[]',is_official boolean not null default true,is_demo boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.participation_submissions(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete restrict,confirmation_reference text not null unique,county text,channel text not null check(channel in ('web','whatsapp_demo','whatsapp_provider')),free_text text check(length(free_text)<=2000),consent boolean not null check(consent),consented_at timestamptz not null default now(),duplicate_hash text,submitted_at timestamptz not null default now(),is_demo boolean not null default false);
create table if not exists public.participation_submission_answers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.participation_submissions on delete cascade,question_id uuid not null references public.participation_questions on delete restrict,answer jsonb not null,created_at timestamptz not null default now(),unique(submission_id,question_id));
create table if not exists public.participation_social_mentions(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete cascade,platform text not null,public_post_reference text not null,public_handle text,source_url text not null,content text not null,fetched_at timestamptz not null,hashtags text[] not null default '{}',sentiment text check(sentiment in ('supportive','skeptical','mixed','neutral')),sentiment_confidence text check(sentiment_confidence in ('low','medium','high')),moderation_status text not null default 'pending' check(moderation_status in ('pending','approved','restricted')),provenance text not null,is_demo boolean not null default false,created_at timestamptz not null default now(),unique(platform,public_post_reference));
create table if not exists public.participation_clusters(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete cascade,source_type text not null check(source_type in ('submission','social')),label text not null,keywords text[] not null default '{}',is_demo boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.participation_cluster_members(id uuid primary key default gen_random_uuid(),cluster_id uuid not null references public.participation_clusters on delete cascade,submission_id uuid references public.participation_submissions on delete cascade,social_mention_id uuid references public.participation_social_mentions on delete cascade,created_at timestamptz not null default now(),check(num_nonnulls(submission_id,social_mention_id)=1));
create table if not exists public.participation_moderation_flags(id uuid primary key default gen_random_uuid(),submission_id uuid references public.participation_submissions on delete cascade,social_mention_id uuid references public.participation_social_mentions on delete cascade,reason text not null,recommendation text not null default 'Needs human review.' check(recommendation='Needs human review.'),status text not null default 'pending' check(status in ('pending','confirmed','dismissed','needs_more_information')),reviewed_by uuid references auth.users,reviewed_at timestamptz,review_notes text,is_demo boolean not null default false,created_at timestamptz not null default now(),check(num_nonnulls(submission_id,social_mention_id)=1));
create table if not exists public.participation_official_responses(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.participation_opportunities on delete cascade,status text not null default 'not_yet_submitted' check(status in ('not_yet_submitted','submitted','received','under_consideration','formal_response_published','closed','awaiting_response')),date_submitted date,receiving_institution text,official_reference text,official_response_url text,response_notes text,last_updated_at timestamptz not null default now(),is_demo boolean not null default false,unique(opportunity_id));
create table if not exists public.participation_governance_settings(id uuid primary key default gen_random_uuid(),custodian_name text,custodian_type text not null default 'Not yet decided.',custodian_status text not null default 'Not yet decided.',data_residency_location text,retention_days integer check(retention_days>0),privacy_contact text,public_methodology text,minimum_reporting_threshold integer not null default 5 check(minimum_reporting_threshold>=5),updated_by uuid references auth.users,updated_at timestamptz not null default now());
create table if not exists public.participation_analysis_runs(id uuid primary key default gen_random_uuid(),opportunity_id uuid references public.participation_opportunities on delete cascade,operation text not null,provider text not null default 'local-demo',parameters jsonb not null default '{}',status text not null check(status in ('started','completed','failed')),created_by uuid references auth.users,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.participation_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users,action text not null,target_table text not null,target_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists participation_opportunities_feed_idx on public.participation_opportunities(status,closes_at);create index if not exists participation_questions_opportunity_idx on public.participation_questions(opportunity_id,position);create index if not exists participation_submissions_aggregate_idx on public.participation_submissions(opportunity_id,submitted_at,channel,county);create index if not exists participation_social_opportunity_idx on public.participation_social_mentions(opportunity_id,fetched_at);create index if not exists participation_flags_queue_idx on public.participation_moderation_flags(status,created_at);create index if not exists participation_audit_actor_idx on public.participation_audit_logs(actor_id,created_at);
alter table public.participation_opportunities enable row level security;alter table public.participation_questions enable row level security;alter table public.participation_source_documents enable row level security;alter table public.participation_submissions enable row level security;alter table public.participation_submission_answers enable row level security;alter table public.participation_social_mentions enable row level security;alter table public.participation_clusters enable row level security;alter table public.participation_cluster_members enable row level security;alter table public.participation_moderation_flags enable row level security;alter table public.participation_official_responses enable row level security;alter table public.participation_governance_settings enable row level security;alter table public.participation_analysis_runs enable row level security;alter table public.participation_audit_logs enable row level security;
do $$ declare t text; begin foreach t in array array['participation_opportunities','participation_questions','participation_source_documents','participation_submissions','participation_submission_answers','participation_social_mentions','participation_clusters','participation_cluster_members','participation_moderation_flags','participation_official_responses','participation_governance_settings','participation_analysis_runs','participation_audit_logs'] loop execute format('drop policy if exists staff_all on public.%I',t);execute format('create policy staff_all on public.%I for all to authenticated using (public.participation_is_staff()) with check (public.participation_is_staff())',t);end loop; end $$;
drop policy if exists public_published_opportunities on public.participation_opportunities;create policy public_published_opportunities on public.participation_opportunities for select to anon,authenticated using(status in ('open','closed'));
drop policy if exists public_published_questions on public.participation_questions;create policy public_published_questions on public.participation_questions for select to anon,authenticated using(exists(select 1 from public.participation_opportunities o where o.id=opportunity_id and o.status in ('open','closed')));
drop policy if exists public_sources on public.participation_source_documents;create policy public_sources on public.participation_source_documents for select to anon,authenticated using(exists(select 1 from public.participation_opportunities o where o.id=opportunity_id and o.status in ('open','closed')));
drop policy if exists public_approved_social on public.participation_social_mentions;create policy public_approved_social on public.participation_social_mentions for select to anon,authenticated using(moderation_status='approved' and exists(select 1 from public.participation_opportunities o where o.id=opportunity_id and o.status in ('open','closed')));
drop policy if exists public_clusters on public.participation_clusters;create policy public_clusters on public.participation_clusters for select to anon,authenticated using(exists(select 1 from public.participation_opportunities o where o.id=opportunity_id and o.status in ('open','closed')));
drop policy if exists public_official_responses on public.participation_official_responses;create policy public_official_responses on public.participation_official_responses for select to anon,authenticated using(exists(select 1 from public.participation_opportunities o where o.id=opportunity_id and o.status in ('open','closed')));
-- Deliberately no anon policies for submissions, answers, cluster membership, flags, audit logs, analysis runs, or governance internals.
create or replace view public.participation_public_counts with (security_invoker=false,security_barrier=true) as select o.id opportunity_id,count(s.id)::bigint response_count from public.participation_opportunities o left join public.participation_submissions s on s.opportunity_id=o.id where o.status in ('open','closed') group by o.id;
revoke all on public.participation_public_counts from public;grant select on public.participation_public_counts to anon,authenticated;
insert into public.participation_governance_settings(custodian_type,custodian_status,minimum_reporting_threshold) select 'Not yet decided.','Not yet decided.',5 where not exists(select 1 from public.participation_governance_settings);
insert into public.participation_opportunities(slug,title,institution,opportunity_type,scope,county,opens_at,closes_at,status,official_source_url,plain_summary,key_issues,channels,is_demo) values
('beyond-2030','Beyond Vision 2030 — National Development Conversation','State Department for Economic Planning','national_strategy','national',null,'2026-08-01','2026-11-30','open','https://planning.go.ke/','A demo national conversation about priorities after Vision 2030.','["Jobs and enterprise","Infrastructure","Education and skills","Governance and trust","Cost of living","Other"]','{web,whatsapp_demo}',true),
('finance-bill-2026','Finance Bill 2026 — Committee Stage Submissions','National Assembly','bill_legislative','national',null,'2026-09-01','2026-10-15','open','https://www.parliament.go.ke/','A demonstration consultation on proposed revenue measures.','["Household costs","Small business"]','{web}',true),
('emc-budget-2026','Elgeyo Marakwet County Budget — FY2026/27 Priorities','County Government of Elgeyo Marakwet','county_budget','county','Elgeyo Marakwet','2026-06-01','2026-07-01','closed','https://elgeyomarakwet.go.ke/','A demonstration county priority-setting exercise.','["Roads","Health","Water"]','{web}',true) on conflict(slug) do nothing;
insert into public.participation_questions(opportunity_id,prompt,question_type,options,position,is_demo) select id,'Which priority matters most to you?','single',key_issues,1,true from public.participation_opportunities o where is_demo and not exists(select 1 from public.participation_questions q where q.opportunity_id=o.id);
insert into public.participation_official_responses(opportunity_id,status,receiving_institution,is_demo) select id,case when slug='beyond-2030' then 'under_consideration' else 'awaiting_response' end,institution,true from public.participation_opportunities on conflict(opportunity_id) do nothing;
insert into public.participation_social_mentions(opportunity_id,platform,public_post_reference,public_handle,source_url,content,fetched_at,hashtags,sentiment,sentiment_confidence,moderation_status,provenance,is_demo) select id,'X','demo-001','@demo_citizen','https://example.com/public-post/demo-001','Tafadhali jobs na affordable education ziwe priority.','2026-09-01','{Vision2030}','supportive','medium','approved','Seeded demonstration',true from public.participation_opportunities where slug='beyond-2030' on conflict(platform,public_post_reference) do nothing;
insert into public.participation_clusters(opportunity_id,source_type,label,keywords,is_demo) select id,'social','Jobs and education','{jobs,education}',true from public.participation_opportunities o where slug='beyond-2030' and not exists(select 1 from public.participation_clusters c where c.opportunity_id=o.id and c.label='Jobs and education');
